import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { useState } from "react";
import { ActivityIndicator, Pressable, StyleSheet, Text, TextInput, View } from "react-native";
import { ModuleCard } from "../../ui/ModuleCard";
import { Screen } from "../../ui/Screen";
import { colors, radius, spacing } from "../../ui/tokens";
import { firebaseAuth } from "../auth/firebase";
import { getVendorWorkspace, saveVendorBankAccount } from "./vendor.api";

const providers = ["BANK", "BKASH", "NAGAD", "ROCKET"] as const;
type Provider = (typeof providers)[number];
export function VendorPayoutSettingsScreen() {
  const user = firebaseAuth?.currentUser ?? null; const queryClient = useQueryClient();
  const [form, setForm] = useState({ provider: "BANK" as Provider, accountName: "", accountNumber: "", confirmAccountNumber: "" });
  const workspace = useQuery({ queryKey: ["vendor", "workspace"], queryFn: () => getVendorWorkspace(user!), enabled: Boolean(user) });
  const save = useMutation({ mutationFn: () => saveVendorBankAccount(user!, { provider: form.provider, accountName: form.accountName.trim(), accountNumber: form.accountNumber.trim(), isDefault: true }), onSuccess: async () => { setForm({ provider: "BANK", accountName: "", accountNumber: "", confirmAccountNumber: "" }); await queryClient.invalidateQueries({ queryKey: ["vendor", "workspace"] }); } });
  const valid = form.accountName.trim().length >= 2 && form.accountNumber.trim().length >= 8 && form.accountNumber === form.confirmAccountNumber;
  return <Screen eyebrow="SELLER CENTER" title="Bank & payout settings" description="Manage verified payout destinations for seller withdrawals.">
    <ModuleCard title="Payout security" meta="Account numbers are encrypted at rest."><Text style={styles.body}>Use an account owned by you or your registered business. Saved numbers remain masked and cannot be viewed in full.</Text></ModuleCard>
    <ModuleCard title="Saved payout accounts" meta={`${workspace.data?.bankAccounts.length ?? 0} account(s)`}>{workspace.isLoading ? <ActivityIndicator color={colors.primary} /> : null}{workspace.data?.bankAccounts.map((account) => <View key={account.id} style={styles.account}><View><Text style={styles.accountName}>{account.provider} · {account.accountNumberMasked}</Text><Text style={styles.muted}>{account.accountName}</Text></View><Text style={[styles.badge, account.verifiedAt ? styles.verified : styles.pending]}>{account.verifiedAt ? "Verified" : account.isDefault ? "Default" : "Saved"}</Text></View>)}{!workspace.isLoading && !workspace.data?.bankAccounts.length ? <Text style={styles.muted}>No payout account saved yet.</Text> : null}</ModuleCard>
    <ModuleCard title="Add payout account" meta="The newest account becomes your default."><Text style={styles.label}>Payout method</Text><View style={styles.providers}>{providers.map((provider) => <Pressable key={provider} onPress={() => setForm({ ...form, provider })} style={[styles.chip, form.provider === provider && styles.activeChip]}><Text style={[styles.chipText, form.provider === provider && styles.activeChipText]}>{provider === "BANK" ? "Bank transfer" : provider}</Text></Pressable>)}</View><Field label={form.provider === "BANK" ? "Bank account name" : "Account holder name"} onChangeText={(accountName) => setForm({ ...form, accountName })} value={form.accountName} /><Field keyboardType="number-pad" label={form.provider === "BANK" ? "Bank account number" : `${form.provider} number`} onChangeText={(accountNumber) => setForm({ ...form, accountNumber })} secureTextEntry value={form.accountNumber} /><Field keyboardType="number-pad" label="Confirm account number" onChangeText={(confirmAccountNumber) => setForm({ ...form, confirmAccountNumber })} secureTextEntry value={form.confirmAccountNumber} />{form.confirmAccountNumber && form.accountNumber !== form.confirmAccountNumber ? <Text style={styles.error}>Account numbers do not match.</Text> : null}<Pressable disabled={!valid || save.isPending} onPress={() => save.mutate()} style={[styles.button, (!valid || save.isPending) && styles.disabled]}>{save.isPending ? <ActivityIndicator color="#fff" /> : <Text style={styles.buttonText}>Save payout account</Text>}</Pressable>{save.error ? <Text style={styles.error}>{save.error.message}</Text> : null}</ModuleCard>
  </Screen>;
}
function Field({ label, ...props }: React.ComponentProps<typeof TextInput> & { label: string }) { return <View style={styles.field}><Text style={styles.label}>{label}</Text><TextInput placeholderTextColor={colors.muted} style={styles.input} {...props} /></View>; }
const styles = StyleSheet.create({ body: { color: colors.text, lineHeight: 21 }, muted: { color: colors.muted, fontSize: 12 }, account: { alignItems: "center", borderBottomColor: colors.border, borderBottomWidth: 1, flexDirection: "row", justifyContent: "space-between", paddingVertical: spacing.sm }, accountName: { color: colors.text, fontWeight: "900" }, badge: { borderRadius: radius.pill, fontSize: 10, fontWeight: "900", overflow: "hidden", paddingHorizontal: 9, paddingVertical: 5 }, verified: { backgroundColor: "#ecfdf5", color: "#047857" }, pending: { backgroundColor: "#fff7ed", color: "#c2410c" }, providers: { flexDirection: "row", flexWrap: "wrap", gap: spacing.sm }, chip: { borderColor: colors.border, borderRadius: radius.pill, borderWidth: 1, paddingHorizontal: 12, paddingVertical: 8 }, activeChip: { backgroundColor: colors.primary, borderColor: colors.primary }, chipText: { color: colors.text, fontSize: 11, fontWeight: "800" }, activeChipText: { color: "#fff" }, field: { gap: 5 }, label: { color: colors.text, fontSize: 12, fontWeight: "800" }, input: { backgroundColor: "#f8fafc", borderColor: colors.border, borderRadius: radius.md, borderWidth: 1, color: colors.text, minHeight: 46, paddingHorizontal: 12 }, button: { alignItems: "center", backgroundColor: colors.primary, borderRadius: radius.md, justifyContent: "center", minHeight: 46 }, disabled: { opacity: 0.45 }, buttonText: { color: "#fff", fontWeight: "900" }, error: { color: colors.danger, fontSize: 12 } });
